+class ContactViewTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @BeforeAll
+    static void launchBrowser() {
+        setup();
+    }
+
+    @AfterAll
+    static void closeBrowser() {
+        cleanup();
+    }
+
+    @BeforeEach
+    void openContactView() throws Exception {
+        setupTest();
+    }
+
+    @AfterEach
+    void closePage() {
+        cleanupTest();
+    }
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void sendsAndClearsAValidMessage() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Ada");
+        EmailFieldElement.getByLabel(page, "Email").setValue("ada@example.test");
+        TextAreaElement.getByLabel(page, "Message").setValue("Hello there");
+
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        TextFieldElement.getByLabel(page, "Name").assertValue("");
+        EmailFieldElement.getByLabel(page, "Email").assertValue("");
+        TextAreaElement.getByLabel(page, "Message").assertValue("");
+        send.assertDisabled();
+        assertThat(page.getByText("Ada")).isVisible();
+        assertThat(page.getByText("Hello there")).isVisible();
+    }
+
+    @Test
+    void showsTheRequiredValidationMessages() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Give an e-mail address or a phone number");
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+    }
+
+    @Test
+    void enterSubmitsTheForm() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Grace");
+        EmailFieldElement.getByLabel(page, "Email").setValue("grace@example.test");
+        TextAreaElement.getByLabel(page, "Message").setValue("Sent with Enter");
+
+        page.keyboard().press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        ButtonElement.getByText(page, "Send").assertDisabled();
+    }
+
+    @Test
+    void asksBeforeDiscardingEnteredText() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Ada");
+        page.getByText("About", new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).click();
+
+        assertThat(page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Keep editing"))).isVisible();
+        page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.getByRole(com.microsoft.playwright.options.AriaRole.HEADING,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+}
